 protected override void OnMouseMove(MouseEventArgs e){if(Control.MouseButtons==MouseButtons.None){Form f=FindForm();if(f!=null&&HasMenu(f)){var item=GetItemAt(e.Location) as ToolStripDropDownItem;if(item==null||!item.DropDown.Visible)return;}}base.OnMouseMove(e);}
