 class ThemeComboBox:ComboBox {
 internal ThemeComboBox(){FlatStyle=FlatStyle.Flat;DrawMode=DrawMode.OwnerDrawFixed;ItemHeight=25;IntegralHeight=false;MaxDropDownItems=12;}
