 protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;Color fill=selected?ControlPaint.Light(BackColor,.12f):BackColor;using(var b=new SolidBrush(fill))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,Convert.ToString(Items[e.Index]),Font,new Rectangle(e.Bounds.X+7,e.Bounds.Y+3,e.Bounds.Width-14,e.Bounds.Height-4),ForeColor,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);}
