static class CompanionPalette {
 internal static Color Mix(Color a,Color b,float amount){return Color.FromArgb((int)(a.R+(b.R-a.R)*amount),(int)(a.G+(b.G-a.G)*amount),(int)(a.B+(b.B-a.B)*amount));}
 internal static Color[] For(string name){string[] c;switch((name??"Sketchbook").ToLowerInvariant()){case "charcoal":c=new[]{"#202329","#2b2f36","#ecede9","#b6bdc5","#d6c89e"};break;case "forest":c=new[]{"#203630","#334e40","#f2ebd2","#b9cabb","#b7d5a0"};break;case "blueprint":c=new[]{"#1a3146","#2b465c","#deeff5","#acc6d5","#91d9f4"};break;case "plum":c=new[]{"#27202e","#352c3f","#f0e7f4","#bfafc9","#ddb4db"};break;case "sticky cream":c=new[]{"#fff1bd","#fff1bd","#39362f","#827c69","#c18b3c"};break;case "sticky rose":c=new[]{"#f4dce4","#f4dce4","#49343d","#8a6c78","#b66388"};break;case "sticky sage":c=new[]{"#deeadb","#deeadb","#2e4133","#6b826e","#548260"};break;case "sticky slate":c=new[]{"#343b43","#343b43","#f0f0e8","#b5bdc5","#99b8ca"};break;case "paper":c=new[]{"#f5eedf","#fffbf1","#483a2f","#786f61","#8f663e"};break;case "candy":c=new[]{"#f0e6ef","#fff3f8","#533650","#7d6075","#9e4e87"};break;default:c=new[]{"#e9e5dd","#f8f6f0","#27363a","#69716b","#486d6e"};break;}return c.Select(ColorTranslator.FromHtml).ToArray();}
 internal static void Items(ToolStripItemCollection items,Color[] p){foreach(ToolStripItem item in items){item.ForeColor=p[2];item.BackColor=p[1];var menu=item as ToolStripDropDownItem;if(menu!=null){menu.DropDown.Renderer=new ToolStripProfessionalRenderer(new CompanionColors(p[1],p[0],p[4]));menu.DropDown.BackColor=p[1];Items(menu.DropDownItems,p);}}}
 internal static void Apply(Control c,string theme){Apply(c,For(theme));}internal static void Apply(Control c,Color[] p){c.BackColor=c is Form?p[0]:p[1];c.ForeColor=p[2];var link=c as LinkLabel;if(link!=null){link.LinkColor=p[4];link.ActiveLinkColor=p[2];link.VisitedLinkColor=p[4];}var button=c as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=p[3];button.FlatAppearance.MouseOverBackColor=p[0];button.Padding=c.Parent is ThemeNumber?Padding.Empty:new Padding(5,2,5,2);}var tabs=c as ThemeTabs;if(tabs!=null){tabs.Fill=p[1];tabs.TextInk=p[2];tabs.Invalidate();}var slider=c as ThemeSlider;if(slider!=null){slider.Accent=p[4];slider.Invalidate();}var combo=c as ComboBox;if(combo!=null)combo.FlatStyle=FlatStyle.Flat;var strip=c as ToolStrip;if(strip!=null){strip.Renderer=new ToolStripProfessionalRenderer(new CompanionColors(p[1],p[0],p[4]));Items(strip.Items,p);}NativeScrollTheme.Apply(c,p[0].GetBrightness()<.4f);foreach(Control child in c.Controls)Apply(child,p);}
}

sealed class ThemeTasks:CheckedListBox {
