 protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==0xF&&SolidGlyphs&&TransparencyPaint!=null)TransparencyPaint(this);}
 internal ThemeTasks(){ItemCheck+=(s,e)=>{if(IsHandleCreated)BeginInvoke((Action)(()=>Invalidate()));};BorderStyle=BorderStyle.None;IntegralHeight=false;ItemHeight=34;}
 protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0||e.Index>=Items.Count)return;if(SolidGlyphs){using(var clear=new SolidBrush(BackColor))e.Graphics.FillRectangle(clear,e.Bounds);return;}bool selected=(e.State&DrawItemState.Selected)!=0;Color fill=selected?ControlPaint.Light(BackColor,.12f):BackColor;using(var b=new SolidBrush(fill))e.Graphics.FillRectangle(b,e.Bounds);var box=new Rectangle(e.Bounds.X+8,e.Bounds.Y+Math.Max(2,(e.Bounds.Height-16)/2),16,16);using(var p=new Pen(ForeColor,1))e.Graphics.DrawRectangle(p,box);bool done=GetItemChecked(e.Index);if(done)using(var p=new Pen(ForeColor,2)){e.Graphics.DrawLine(p,box.X+3,box.Y+8,box.X+7,box.Y+12);e.Graphics.DrawLine(p,box.X+7,box.Y+12,box.X+13,box.Y+4);}using(var font=new Font(Font,done?FontStyle.Strikeout:FontStyle.Regular))TextRenderer.DrawText(e.Graphics,Convert.ToString(Items[e.Index]),font,new Rectangle(e.Bounds.X+34,e.Bounds.Y+3,e.Bounds.Width-40,e.Bounds.Height-6),done?ControlPaint.Light(ForeColor,.1f):ForeColor,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
