sealed class ThemeNumber:UserControl {
 readonly TextBox input=new TextBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.FixedSingle};decimal minimum=0,maximum=100,value=0,increment=1;int places;internal event EventHandler ValueChanged;
 internal ThemeNumber(){Height=30;Width=120;var more=new Button{Text="+",Dock=DockStyle.Right,Width=26,FlatStyle=FlatStyle.Flat,Padding=Padding.Empty,Margin=Padding.Empty};var less=new Button{Text="−",Dock=DockStyle.Right,Width=26,FlatStyle=FlatStyle.Flat,Padding=Padding.Empty,Margin=Padding.Empty};Controls.Add(input);Controls.Add(less);Controls.Add(more);more.Click+=(s,e)=>Value+=Increment;less.Click+=(s,e)=>Value-=Increment;input.Leave+=(s,e)=>Read();input.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){Read();e.SuppressKeyPress=true;}if(e.KeyCode==Keys.Up){Value+=Increment;e.SuppressKeyPress=true;}if(e.KeyCode==Keys.Down){Value-=Increment;e.SuppressKeyPress=true;}};UpdateText();}
 internal decimal Minimum{get{return minimum;}set{minimum=value;if(maximum<minimum)maximum=minimum;Value=this.value;}}internal decimal Maximum{get{return maximum;}set{maximum=value;if(minimum>maximum)minimum=maximum;Value=this.value;}}internal decimal Increment{get{return increment;}set{increment=value;}}internal int DecimalPlaces{get{return places;}set{places=value;UpdateText();}}
 internal decimal Value{get{return value;}set{decimal next=Math.Max(minimum,Math.Min(maximum,value));bool changed=next!=this.value;this.value=next;UpdateText();if(changed&&ValueChanged!=null)ValueChanged(this,EventArgs.Empty);}}
 protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);int x=Width-52;foreach(Control c in Controls)if(c is Button){c.Dock=DockStyle.None;c.Padding=Padding.Empty;c.MinimumSize=Size.Empty;c.Bounds=new Rectangle(x,0,26,Math.Min(28,Height));x+=26;}input.Dock=DockStyle.None;input.MinimumSize=Size.Empty;input.Bounds=new Rectangle(0,Math.Max(0,(Height-input.PreferredHeight)/2),Math.Max(26,Width-52),input.PreferredHeight);}

 void Read(){decimal next;if(decimal.TryParse(input.Text,out next))Value=next;else UpdateText();}void UpdateText(){input.Text=value.ToString("F"+places);}
}

sealed class NoteListBox:ListBox {
