sealed class ThemeSlider:Control {
 int minimum=0,maximum=100,value=0;bool dragging;internal Color Accent=Color.FromArgb(72,109,110);internal event EventHandler ValueChanged;internal int TickFrequency{get;set;}internal TickStyle TickStyle{get;set;}internal int SmallChange{get;set;}internal int LargeChange{get;set;}
 internal ThemeSlider(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Height=42;Width=250;TabStop=true;Cursor=Cursors.Hand;AccessibleRole=AccessibleRole.Slider;SmallChange=1;LargeChange=10;}
 internal int Minimum{get{return minimum;}set{minimum=value;Value=this.value;}}internal int Maximum{get{return maximum;}set{maximum=value;Value=this.value;}}
